insert into public.foodkeeper_shelf_life
  (id, name, subtitle, category, subcategory, keywords,
   pantry_min_days, pantry_max_days, pantry_open_min_days, pantry_open_max_days,
   fridge_min_days, fridge_max_days, fridge_open_min_days, fridge_open_max_days,
   freezer_min_days, freezer_max_days,
   tips, source, source_url)
values
  (10161, 'Sugar Apple', NULL, 'Produce', 'Tropical fruit', 'sugar apple custard apple sweetsop tropical fruit', 2, 5, NULL, NULL, 5, 10, 1, 2, 180, 365, 'Ripen at room temperature until skin softens slightly. Refrigerate ripe fruit to extend shelf life. Freeze pulp in airtight containers for longer storage.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10162, 'Soursop', NULL, 'Produce', 'Tropical fruit', 'soursop graviola guanabana tropical fruit', 2, 5, NULL, NULL, 5, 10, 1, 2, 180, 365, 'Ripen at room temperature until skin yields to gentle pressure. Refrigerate ripe fruit immediately. Freeze pulp or whole fruit for extended storage.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10163, 'Mangosteen', NULL, 'Produce', 'Tropical fruit', 'mangosteen tropical fruit purple', 3, 7, NULL, NULL, 10, 21, 2, 3, 180, 365, 'Store in cool, well-ventilated area to prevent mold. Refrigerate for longer shelf life. Freeze segments in airtight containers.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10164, 'Rambutan', NULL, 'Produce', 'Tropical fruit', 'rambutan hairy tropical fruit', 2, 5, NULL, NULL, 7, 14, 1, 2, 180, 365, 'Refrigerate immediately after purchase. Keep in perforated plastic bag to maintain humidity. Freeze whole or peeled for longer storage.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10165, 'Longan', NULL, 'Produce', 'Tropical fruit', 'longan dragon''s eye tropical fruit', 2, 5, NULL, NULL, 7, 14, 2, 3, 180, 365, 'Refrigerate in perforated plastic bag. Shell may darken in cold storage without affecting quality. Freeze whole or peeled.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10166, 'Jackfruit', NULL, 'Produce', 'Tropical fruit', 'jackfruit tropical fruit large', 3, 7, 1, 2, 7, 14, 3, 5, 180, 365, 'Ripen at room temperature until fragrant. Once cut, wrap exposed flesh tightly and refrigerate. Freeze segments in airtight containers.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10167, 'Durian', NULL, 'Produce', 'Tropical fruit', 'durian king of fruits tropical', 2, 4, 1, 1, 5, 10, 2, 3, 180, 365, 'Ripen at room temperature. Once ripe, refrigerate immediately in sealed container to contain odor. Freeze segments in airtight containers.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10168, 'Loquat', NULL, 'Produce', 'Stone fruit', 'loquat medlar japanese plum', 2, 5, NULL, NULL, 7, 14, 2, 3, 180, 365, 'Ripen at room temperature until soft. Refrigerate ripe fruit in perforated bag. Freeze whole or peeled.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10169, 'Quince', NULL, 'Produce', 'Pome fruit', 'quince pome fruit cooking', 7, 14, NULL, NULL, 21, 60, 3, 7, 180, 365, 'Store in cool, dark place away from other fruits. Refrigerate for extended storage. Peel and freeze raw or cooked.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10170, 'Medlar', NULL, 'Produce', 'Pome fruit', 'medlar bletting pome fruit', 7, 14, NULL, NULL, 21, 60, 3, 7, 180, 365, 'Medlars require bletting (softening) before eating; store at room temperature until very soft, then refrigerate. Freeze whole or processed.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10171, 'Tamarillo', NULL, 'Produce', 'Tropical fruit', 'tamarillo tree tomato tropical fruit', 3, 7, NULL, NULL, 7, 14, NULL, NULL, 180, 365, 'Ripen at room temperature until soft; refrigerate when ripe. Freeze whole or puréed for extended storage.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10172, 'Cape Gooseberry', NULL, 'Produce', 'Tropical berry', 'cape gooseberry physalis ground cherry tropical', 3, 7, NULL, NULL, 14, 21, NULL, NULL, 180, 365, 'Store in husk for longer shelf life. Refrigerate for best quality; husked berries deteriorate faster.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10173, 'Carambola', NULL, 'Produce', 'Tropical fruit', 'carambola star fruit tropical', 2, 5, NULL, NULL, 7, 14, NULL, NULL, 180, 365, 'Ripen at room temperature; refrigerate when ripe. Slice and freeze on trays before bagging for best texture.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10174, 'Sapote', 'white or brown', 'Produce', 'Tropical fruit', 'sapote white brown tropical fruit', 2, 7, NULL, NULL, 7, 14, NULL, NULL, 180, 365, 'Ripen at room temperature until soft; refrigerate when ripe. Freeze pulp in airtight containers.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10175, 'Mamey Sapote', NULL, 'Produce', 'Tropical fruit', 'mamey sapote tropical fruit', 3, 10, NULL, NULL, 7, 14, NULL, NULL, 180, 365, 'Ripen at room temperature; refrigerate when soft. Freeze pulp in airtight containers for up to one year.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10176, 'Black Sapote', NULL, 'Produce', 'Tropical fruit', 'black sapote chocolate fruit tropical', 2, 7, NULL, NULL, 7, 14, NULL, NULL, 180, 365, 'Ripen at room temperature until very soft; refrigerate when ripe. Freeze pulp in airtight containers.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10177, 'Pomelo', NULL, 'Produce', 'Citrus fruit', 'pomelo citrus tropical grapefruit', 7, 14, NULL, NULL, 21, 42, 7, 14, 180, 365, 'Store at room temperature or refrigerate for longer shelf life. Once cut, cover and refrigerate; use within 1–2 weeks.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10178, 'Buddha''s Hand', NULL, 'Produce', 'Citrus fruit', 'buddha''s hand citrus fragrant lemon', 7, 14, NULL, NULL, 21, 42, NULL, NULL, 180, 365, 'Store at room temperature or refrigerate. Primarily used for zest and fragrance; minimal juice. Refrigerate for extended storage.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10179, 'Calamansi', NULL, 'Produce', 'Citrus fruit', 'calamansi citrus lime tropical', 5, 10, NULL, NULL, 14, 21, NULL, NULL, 180, 365, 'Refrigerate for best shelf life. Freeze juice in ice-cube trays for convenient portioning.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10180, 'Finger Lime', NULL, 'Produce', 'Citrus fruit', 'finger lime caviar lime citrus tropical', 3, 7, NULL, NULL, 14, 21, NULL, NULL, 180, 365, 'Refrigerate for best quality. Delicate skin; handle gently. Freeze whole or extract juice for longer storage.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10181, 'Blood Orange', NULL, 'Produce', 'Citrus', 'blood orange citrus fruit', 7, 14, NULL, NULL, 14, 28, NULL, NULL, NULL, NULL, 'Store in a cool, dark place or refrigerate for extended shelf life. Whole fruit keeps longer than cut fruit.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-do-oranges-last'),
  (10182, 'Cara Cara Orange', NULL, 'Produce', 'Citrus', 'cara cara orange citrus fruit', 7, 14, NULL, NULL, 14, 28, NULL, NULL, NULL, NULL, 'Store in a cool, dark place or refrigerate for extended shelf life. Whole fruit keeps longer than cut fruit.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-do-oranges-last'),
  (10183, 'Meyer Lemon', NULL, 'Produce', 'Citrus', 'meyer lemon citrus fruit', 7, 14, NULL, NULL, 14, 21, NULL, NULL, NULL, NULL, 'Refrigerate for best longevity. Meyer lemons are thinner-skinned than standard lemons and spoil faster.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-do-lemons-last'),
  (10184, 'Bergamot', 'citrus fruit', 'Produce', 'Citrus', 'bergamot citrus fruit', 7, 14, NULL, NULL, 14, 21, NULL, NULL, NULL, NULL, 'Store in a cool, dark place or refrigerate. Bergamot is fragile; handle gently to avoid bruising.', 'Extension', NULL),
  (10185, 'Sudachi', NULL, 'Produce', 'Citrus', 'sudachi citrus fruit japanese', 7, 14, NULL, NULL, 14, 21, NULL, NULL, NULL, NULL, 'Refrigerate for extended storage. Sudachi is best used fresh; juice can be frozen separately.', 'Extension', NULL),
  (10186, 'Kumquat', NULL, 'Produce', 'Citrus', 'kumquat citrus fruit', 7, 14, NULL, NULL, 14, 28, NULL, NULL, NULL, NULL, 'Refrigerate for best shelf life. Kumquats are eaten whole, skin and all; discard any with soft spots.', 'Extension', NULL),
  (10187, 'Cherry Plum', NULL, 'Produce', 'Stone fruit', 'cherry plum fruit', 1, 3, NULL, NULL, 3, 7, NULL, NULL, NULL, NULL, 'Refrigerate immediately after purchase. Cherry plums are highly perishable; use within a few days.', 'Extension', NULL),
  (10188, 'Mirabelle', 'plum', 'Produce', 'Stone fruit', 'mirabelle plum fruit', 2, 5, NULL, NULL, 5, 10, NULL, NULL, NULL, NULL, 'Refrigerate for extended storage. Mirabelles are delicate; handle carefully to avoid bruising.', 'Extension', NULL),
  (10189, 'Damson', 'plum', 'Produce', 'Stone fruit', 'damson plum fruit', 3, 7, NULL, NULL, 7, 14, NULL, NULL, NULL, NULL, 'Refrigerate for best shelf life. Damsons are firmer than other plums and keep longer.', 'Extension', NULL),
  (10190, 'Greengage', 'plum', 'Produce', 'Stone fruit', 'greengage plum fruit', 2, 5, NULL, NULL, 5, 10, NULL, NULL, NULL, NULL, 'Refrigerate for extended storage. Greengages are delicate; use within a week for best flavor.', 'Extension', NULL),
  (10191, 'Pluot', NULL, 'Produce', 'Stone fruit', 'pluot plum apricot hybrid stone fruit', 1, 3, NULL, NULL, 5, 7, NULL, NULL, 180, 365, 'Refrigerate when ripe. Freeze whole or sliced; thaw in refrigerator before use.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10192, 'Apriplum', NULL, 'Produce', 'Stone fruit', 'apriplum apricot plum hybrid stone fruit', 1, 3, NULL, NULL, 5, 7, NULL, NULL, 180, 365, 'Refrigerate when ripe. Freeze whole or sliced; thaw in refrigerator before use.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10193, 'Honeyberry', NULL, 'Produce', 'Berry', 'honeyberry lonicera berry blue honeysuckle', 0, 1, NULL, NULL, 3, 5, NULL, NULL, 180, 365, 'Refrigerate immediately. Very delicate; use or freeze within 1–2 days of purchase.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10194, 'Mulberry', NULL, 'Produce', 'Berry', 'mulberry morus berry', 0, 1, NULL, NULL, 2, 3, NULL, NULL, 180, 365, 'Highly perishable; refrigerate immediately and use within 1–2 days. Freeze for longer storage.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10195, 'Marionberry', NULL, 'Produce', 'Berry', 'marionberry blackberry hybrid berry', 0, 1, NULL, NULL, 2, 4, NULL, NULL, 180, 365, 'Refrigerate immediately. Use within 2–3 days or freeze for longer storage.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10196, 'Boysenberry', NULL, 'Produce', 'Berry', 'boysenberry blackberry hybrid berry', 0, 1, NULL, NULL, 2, 4, NULL, NULL, 180, 365, 'Refrigerate immediately. Use within 2–3 days or freeze for longer storage.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10197, 'Olallieberry', NULL, 'Produce', 'Berry', 'olallieberry blackberry hybrid berry', 0, 1, NULL, NULL, 2, 4, NULL, NULL, 180, 365, 'Refrigerate immediately. Use within 2–3 days or freeze for longer storage.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10198, 'Salmonberry', NULL, 'Produce', 'Berry', 'salmonberry rubus berry', 0, 1, NULL, NULL, 2, 3, NULL, NULL, 180, 365, 'Highly perishable; refrigerate immediately and use within 1–2 days. Freeze for longer storage.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10199, 'Cloudberry', NULL, 'Produce', 'Berry', 'cloudberry rubus berry', 0, 1, NULL, NULL, 2, 3, NULL, NULL, 180, 365, 'Highly perishable; refrigerate immediately and use within 1–2 days. Freeze for longer storage.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10200, 'Currant', NULL, 'Produce', 'Berry', 'currant ribes berry black red white', 0, 1, NULL, NULL, 5, 7, NULL, NULL, 180, 365, 'Refrigerate immediately. Currants keep longer than most berries; freeze for extended storage.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-i-store-fresh-fruit'),
  (10201, 'Gooseberry', NULL, 'Produce', 'Berries', 'gooseberry fresh berry fruit', NULL, NULL, NULL, NULL, 3, 7, 3, 7, 180, 365, 'Store unwashed in a breathable container on a refrigerator shelf. Freeze whole or halved on a tray before bagging for longer storage.', 'Extension', 'https://www.extension.org'),
  (10202, 'Elderberry', 'fresh', 'Produce', 'Berries', 'elderberry fresh berry fruit', NULL, NULL, NULL, NULL, 2, 5, 2, 5, 180, 365, 'Refrigerate unwashed in a shallow container. Elderberries are delicate; freeze promptly if not using within 2–3 days.', 'Extension', 'https://www.extension.org'),
  (10203, 'Aronia Berry', 'fresh', 'Produce', 'Berries', 'aronia berry chokeberry fresh fruit', NULL, NULL, NULL, NULL, 3, 7, 3, 7, 180, 365, 'Store unwashed in a breathable container in the coldest part of the refrigerator. Freeze whole on a tray before bagging.', 'Extension', 'https://www.extension.org'),
  (10204, 'Goji Berry', 'dried', 'Shelf Stable Foods', 'Dried fruits', 'goji berry wolfberry dried fruit', 180, 365, 90, 180, NULL, NULL, 180, 365, 365, 730, 'Store in an airtight container in a cool, dry place away from light. Refrigerate or freeze after opening to extend shelf life and prevent moisture absorption.', 'Manufacturer', NULL),
  (10205, 'Acai Berry', 'frozen pulp or powder', 'Food Purchased Frozen', 'Frozen fruit', 'acai berry frozen pulp powder', NULL, NULL, NULL, NULL, NULL, NULL, 3, 5, 180, 365, 'Keep frozen until use. Once thawed or opened, use within 3–5 days if refrigerated. Do not refreeze thawed pulp.', 'Manufacturer', NULL),
  (10206, 'Maqui Berry', 'dried or powder', 'Shelf Stable Foods', 'Dried fruits and powders', 'maqui berry dried powder fruit', 180, 365, 90, 180, NULL, NULL, 180, 365, 365, 730, 'Store in an airtight container away from heat, light, and moisture. Refrigerate or freeze after opening to preserve potency.', 'Manufacturer', NULL),
  (10207, 'Sea Buckthorn Berry', 'fresh or frozen', 'Produce', 'Berries', 'sea buckthorn berry fresh frozen fruit', NULL, NULL, NULL, NULL, 3, 7, 3, 7, 180, 365, 'Refrigerate fresh berries unwashed in a breathable container. Freeze whole on a tray before bagging for extended storage.', 'Extension', 'https://www.extension.org'),
  (10208, 'Black Raspberry', 'fresh', 'Produce', 'Berries', 'black raspberry fresh berry fruit', NULL, NULL, NULL, NULL, 2, 4, 2, 4, 180, 365, 'Refrigerate unwashed in a shallow container lined with paper towels. Use quickly or freeze; black raspberries are highly perishable.', 'Extension', 'https://www.extension.org'),
  (10209, 'Pineberry', 'fresh', 'Produce', 'Berries', 'pineberry fresh strawberry fruit', NULL, NULL, NULL, NULL, 3, 7, 3, 7, 180, 365, 'Store unwashed in a breathable container on a refrigerator shelf. Freeze whole or hulled on a tray before bagging.', 'Extension', 'https://www.extension.org'),
  (10210, 'White Strawberry', 'fresh', 'Produce', 'Berries', 'white strawberry fresh berry fruit', NULL, NULL, NULL, NULL, 3, 7, 3, 7, 180, 365, 'Store unwashed in a breathable container on a refrigerator shelf. Freeze whole or hulled on a tray before bagging.', 'Extension', 'https://www.extension.org'),
  (10211, 'Yacon', NULL, 'Produce', 'Root vegetables', 'yacon root tuber peruvian ground apple', NULL, NULL, NULL, NULL, 7, 14, NULL, NULL, 90, 180, 'Store in a perforated plastic bag in the crisper drawer. Use within 1–2 weeks for best texture and sweetness.', 'Extension', NULL),
  (10212, 'Burdock Root', NULL, 'Produce', 'Root vegetables', 'burdock root gobo vegetable', NULL, NULL, NULL, NULL, 14, 21, NULL, NULL, 120, 365, 'Wrap unwashed root in damp paper towels and store in a plastic bag in the crisper. Peel just before use to prevent browning.', 'Extension', NULL),
  (10213, 'Sunchoke', NULL, 'Produce', 'Root vegetables', 'sunchoke jerusalem artichoke tuber', NULL, NULL, NULL, NULL, 7, 14, NULL, NULL, 90, 180, 'Store in a perforated bag in the crisper; they are perishable and best used within 1–2 weeks. Peel just before cooking to prevent discoloration.', 'Extension', NULL),
  (10214, 'Salsify', NULL, 'Produce', 'Root vegetables', 'salsify oyster plant root vegetable', NULL, NULL, NULL, NULL, 14, 21, NULL, NULL, 120, 365, 'Store unwashed in a plastic bag in the crisper. Peel and soak in acidulated water immediately after cutting to prevent browning.', 'Extension', NULL),
  (10215, 'Daikon Radish', NULL, 'Produce', 'Root vegetables', 'daikon radish white radish mooli', NULL, NULL, NULL, NULL, 14, 21, NULL, NULL, 120, 365, 'Remove greens if attached and store in a perforated bag in the crisper. Keeps longer than smaller radish varieties.', 'Extension', NULL),
  (10216, 'Watermelon Radish', NULL, 'Produce', 'Root vegetables', 'watermelon radish red meat radish', NULL, NULL, NULL, NULL, 7, 14, NULL, NULL, 90, 180, 'Store in a perforated bag in the crisper. More delicate than standard daikon; use within 1–2 weeks for best crispness.', 'Extension', NULL),
  (10217, 'Black Radish', NULL, 'Produce', 'Root vegetables', 'black radish spanish radish winter radish', NULL, NULL, NULL, NULL, 14, 21, NULL, NULL, 120, 365, 'Store unwashed in a perforated bag in the crisper. Peel just before use; flesh may discolor slightly but remains safe.', 'Extension', NULL),
  (10218, 'Lotus Root', NULL, 'Produce', 'Root vegetables', 'lotus root renkon rhizome', NULL, NULL, NULL, NULL, 7, 14, NULL, NULL, 90, 180, 'Store in a perforated bag in the crisper. Peel and soak in acidulated water immediately after cutting to prevent browning.', 'Extension', NULL),
  (10219, 'Taro Root', NULL, 'Produce', 'Root vegetables', 'taro root taro corm tropical', 7, 14, NULL, NULL, 14, 21, NULL, NULL, 120, 365, 'Store in a cool, dark, well-ventilated place or in the crisper drawer. Must be cooked before eating; raw taro contains calcium oxalate crystals.', 'Extension', NULL),
  (10220, 'Cassava', NULL, 'Produce', 'Root vegetables', 'cassava yuca manioc root tropical', 3, 7, NULL, NULL, 7, 14, NULL, NULL, 120, 365, 'Store in a cool, dark place or refrigerate. Peel and soak in water if storing peeled. Must be cooked before eating; raw cassava contains cyanogenic compounds.', 'Extension', NULL),
  (10221, 'Yuca', NULL, 'Produce', 'Root vegetables', 'yuca cassava root starchy tuber', 7, 14, NULL, NULL, 14, 21, NULL, NULL, 180, 365, 'Store in a cool, dark, well-ventilated place. Refrigerate for longer storage; peel and wrap cut surfaces tightly to prevent browning.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10222, 'Malanga', NULL, 'Produce', 'Root vegetables', 'malanga taro-like root tuber tropical', 7, 14, NULL, NULL, 14, 21, NULL, NULL, 180, 365, 'Store in a cool, dark place with good air circulation. Refrigerate for extended storage; peel just before cooking to prevent discoloration.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10223, 'Cocoyam', NULL, 'Produce', 'Root vegetables', 'cocoyam taro corm tuber tropical', 7, 14, NULL, NULL, 14, 21, NULL, NULL, 180, 365, 'Store in a cool, dark, well-ventilated area. Refrigerate for longer storage; keep away from moisture to prevent sprouting.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10224, 'Arrowroot', NULL, 'Produce', 'Root vegetables', 'arrowroot tuber starch tropical root', 7, 14, NULL, NULL, 14, 21, NULL, NULL, 180, 365, 'Store in a cool, dark place with good air circulation. Refrigerate for extended storage; keep dry to prevent mold.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10225, 'Rutabaga', NULL, 'Produce', 'Root vegetables', 'rutabaga swede root vegetable', 7, 14, NULL, NULL, 21, 56, NULL, NULL, 180, 365, 'Store in a cool, dark place or refrigerate for best longevity. Remove any protective wax coating before cooking if desired.', 'FDA', 'https://www.fda.gov/food/foodborneillnesscontaminants/buystoreservesafely/ucm258169.htm'),
  (10226, 'Turnip', NULL, 'Produce', 'Root vegetables', 'turnip root vegetable brassica', 7, 14, NULL, NULL, 21, 56, NULL, NULL, 180, 365, 'Store in a cool, dark place or refrigerate. Remove greens if attached before storage to prevent moisture loss from the root.', 'FDA', 'https://www.fda.gov/food/foodborneillnesscontaminants/buystoreservesafely/ucm258169.htm'),
  (10227, 'Sweet Potato Leaves', NULL, 'Produce', 'Leafy greens', 'sweet potato leaves greens leafy vegetable', NULL, NULL, NULL, NULL, 3, 7, NULL, NULL, 180, 365, 'Refrigerate immediately in a plastic bag or container. Use quickly as leaves wilt rapidly; blanch and freeze for longer storage.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10228, 'Cassava Leaves', NULL, 'Produce', 'Leafy greens', 'cassava leaves greens leafy vegetable', NULL, NULL, NULL, NULL, 3, 7, NULL, NULL, 180, 365, 'Refrigerate in a plastic bag immediately. Use within a few days; blanch and freeze for extended storage.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10229, 'Chayote', NULL, 'Produce', 'Squash', 'chayote squash vegetable tropical', 7, 14, NULL, NULL, 14, 21, NULL, NULL, 180, 365, 'Store at room temperature or refrigerate. Chayote keeps well in cool conditions; refrigerate for longer storage.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10230, 'Bitter Melon', NULL, 'Produce', 'Squash', 'bitter melon gourd vegetable tropical', 3, 7, NULL, NULL, 7, 14, NULL, NULL, 180, 365, 'Refrigerate in a plastic bag for best storage. Use within 1–2 weeks; bitterness intensifies with age.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10231, 'Luffa', NULL, 'Produce', 'Squash', 'luffa loofah squash vegetable', 7, 14, NULL, NULL, 14, 21, NULL, NULL, NULL, NULL, 'Store in a cool, dry place or refrigerate. Use before skin becomes very soft or wrinkled.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10232, 'Opo Squash', NULL, 'Produce', 'Squash', 'opo squash bottle gourd calabash vegetable', 7, 14, NULL, NULL, 14, 21, NULL, NULL, NULL, NULL, 'Store in a cool, dry place or refrigerate. Best used within 2–3 weeks; skin hardens with age.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10233, 'Kabocha Squash', NULL, 'Produce', 'Winter squash', 'kabocha squash japanese pumpkin vegetable', 30, 60, NULL, NULL, 60, 90, NULL, NULL, NULL, NULL, 'Store in a cool, dark place away from direct sunlight. Discard if skin becomes soft or shows mold.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10234, 'Delicata Squash', NULL, 'Produce', 'Winter squash', 'delicata squash sweet potato squash vegetable', 14, 30, NULL, NULL, 30, 60, NULL, NULL, NULL, NULL, 'Store in a cool, dry place. Delicata has thinner skin than other winter squash and spoils faster; check regularly.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10235, 'Hubbard Squash', NULL, 'Produce', 'Winter squash', 'hubbard squash blue green winter vegetable', 30, 90, NULL, NULL, 90, 120, NULL, NULL, NULL, NULL, 'Store in a cool, dark place. Hubbard squash keeps longer than most winter varieties; discard if skin is soft or moldy.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10236, 'Carnival Squash', NULL, 'Produce', 'Winter squash', 'carnival squash striped winter vegetable', 14, 30, NULL, NULL, 30, 60, NULL, NULL, NULL, NULL, 'Store in a cool, dry place. Carnival squash has thinner skin than Hubbard; check regularly for soft spots.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10237, 'Sweet Dumpling Squash', NULL, 'Produce', 'Winter squash', 'sweet dumpling squash mini winter vegetable', 14, 30, NULL, NULL, 30, 60, NULL, NULL, NULL, NULL, 'Store in a cool, dry place. Smaller size means faster ripening and shorter storage life than larger winter squash.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10238, 'Romanesco', NULL, 'Produce', 'Brassica', 'romanesco broccoli cauliflower green vegetable', 0, 2, NULL, NULL, 4, 7, NULL, NULL, NULL, NULL, 'Refrigerate immediately in a perforated bag. Use within a week; florets yellow and become woody with age.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10239, 'Black Cauliflower', NULL, 'Produce', 'Brassica', 'black cauliflower purple cauliflower vegetable', 0, 2, NULL, NULL, 4, 7, NULL, NULL, NULL, NULL, 'Refrigerate immediately in a perforated bag. Use within a week; florets may develop brown spots or become soft.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10240, 'Purple Cauliflower', NULL, 'Produce', 'Brassica', 'purple cauliflower vegetable brassica', 0, 2, NULL, NULL, 4, 7, NULL, NULL, NULL, NULL, 'Refrigerate immediately in a perforated bag. Use within a week; florets may develop brown spots or become soft.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10241, 'Brussels Sprout Greens', NULL, 'Produce', 'Leafy Greens', 'brussels sprout greens leafy raw', NULL, NULL, NULL, NULL, 3, 5, 1, 2, 180, 365, 'Store unwashed in a plastic bag in the crisper drawer. Wash just before use to prevent wilting.', 'Extension', 'https://www.extension.org'),
