  (10304, 'Guajillo Chile Dried', NULL, 'Shelf Stable Foods', 'Dried Chiles', 'guajillo chile dried mirasol pepper', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container in a cool, dark, dry place. Chiles remain usable for 1–2 years; freezing extends shelf life.', 'Extension', 'https://nchfp.uga.edu'),
  (10305, 'Pasilla Chile Dried', NULL, 'Shelf Stable Foods', 'Dried Chiles', 'pasilla chile dried chilaca pepper', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container in a cool, dark, dry place. Chiles remain usable for 1–2 years; freezing extends shelf life.', 'Extension', 'https://nchfp.uga.edu'),
