  (10308, 'Achiote Paste', NULL, 'Condiments, Sauces & Canned Goods', 'Prepared Pastes', 'achiote paste annatto recado seasoning', 180, 365, NULL, NULL, NULL, NULL, 30, 60, 180, 365, 'Store unopened in a cool, dark pantry. After opening, refrigerate and use within 1–2 months. Freeze in portions for longer storage.', 'Manufacturer', NULL),
  (10309, 'Sazon Seasoning', NULL, 'Shelf Stable Foods', 'Spices & Seasonings', 'sazon seasoning packet culantro achiote coriander', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container away from heat and moisture. Flavor potency declines gradually over 1–2 years.', 'Manufacturer', NULL),
