  (10311, 'Sofrito', 'fresh or frozen', 'Food Purchased Frozen', 'frozen vegetable paste', 'sofrito frozen fresh puerto rican spanish', NULL, NULL, NULL, NULL, 7, 14, 3, 7, 180, 365, 'Refrigerate fresh sofrito in an airtight container. Freeze in ice-cube trays for portioning.', 'Manufacturer', NULL),
  (10312, 'Masa Harina', NULL, 'Grains, Beans & Pasta', 'corn flour', 'masa harina corn flour dried', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container in a cool, dry place. Protect from moisture and insects.', 'Manufacturer', NULL),
  (10313, 'Masa Preparada', 'fresh corn dough', 'Deli & Prepared Foods', 'fresh dough', 'masa preparada fresh corn dough', NULL, NULL, NULL, NULL, 1, 3, 1, 2, 60, 180, 'Use fresh masa within 1–2 days of purchase. Freeze in airtight bags or containers for longer storage.', 'Manufacturer', NULL),
  (10314, 'Chicharrones', 'fried pork rinds', 'Shelf Stable Foods', 'fried snack', 'chicharrones pork rinds fried snack', 180, 365, 7, 14, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container away from heat and humidity. Once opened, consume within 1–2 weeks for best crispness.', 'Manufacturer', NULL),
  (10315, 'Cotija Cheese', NULL, 'Dairy Products & Eggs', 'fresh cheese', 'cotija cheese mexican fresh crumbly', NULL, NULL, NULL, NULL, 7, 14, 7, 14, 60, 180, 'Keep in original packaging or wrap tightly. Freezing may affect texture; best used thawed in cooked dishes.', 'Manufacturer', NULL),
  (10316, 'Asadero Cheese', NULL, 'Dairy Products & Eggs', 'fresh cheese', 'asadero cheese mexican fresh melting', NULL, NULL, NULL, NULL, 7, 14, 7, 14, 60, 180, 'Store in original packaging or airtight container. Freezing may affect melting quality; use thawed cheese in cooked applications.', 'Manufacturer', NULL),
  (10317, 'Oaxaca Cheese', NULL, 'Dairy Products & Eggs', 'fresh cheese', 'oaxaca cheese mexican fresh string cheese', NULL, NULL, NULL, NULL, 7, 14, 7, 14, 60, 180, 'Keep in original brine or wrap tightly. Freezing may affect texture; best used thawed in cooked dishes.', 'Manufacturer', NULL),
  (10318, 'Crema Mexicana', NULL, 'Dairy Products & Eggs', 'sour cream', 'crema mexicana mexican sour cream', NULL, NULL, NULL, NULL, 14, 21, 7, 14, 90, 180, 'Keep refrigerated at 40 °F or below. Once opened, use within 1–2 weeks. Freezing may separate; thaw in refrigerator and stir before use.', 'Manufacturer', NULL),
  (10319, 'Crema Agria', NULL, 'Dairy Products & Eggs', 'sour cream', 'crema agria sour cream mexican', NULL, NULL, NULL, NULL, 14, 21, 7, 14, 90, 180, 'Keep refrigerated at 40 °F or below. Once opened, use within 1–2 weeks. Freezing may separate; thaw in refrigerator and stir before use.', 'Manufacturer', NULL),
  (10320, 'Dulce de Leche', NULL, 'Shelf Stable Foods', 'Sweetened condensed milk product', 'dulce de leche caramel milk spread', 365, 730, 14, 30, NULL, NULL, 30, 60, 365, 1095, 'Unopened cans keep at room temperature; refrigerate after opening. Freezing extends shelf life significantly.', 'Manufacturer', NULL),
  (10321, 'Cajeta', NULL, 'Shelf Stable Foods', 'Goat milk caramel', 'cajeta goat milk dulce caramel', 365, 730, 14, 30, NULL, NULL, 30, 60, 365, 1095, 'Store unopened at room temperature away from heat. Refrigerate after opening; may crystallize slightly over time.', 'Manufacturer', NULL),
  (10322, 'Piloncillo', NULL, 'Shelf Stable Foods', 'Unrefined cane sugar', 'piloncillo unrefined sugar cone', 730, 3650, 730, 3650, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in airtight container in cool, dry place. Hardens over time; soften by adding a piece of bread or apple to the container.', 'Manufacturer', NULL),
  (10323, 'Mexican Vanilla Extract', NULL, 'Shelf Stable Foods', 'Flavoring extract', 'vanilla extract mexican flavoring', 365, 1095, 365, 1095, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in cool, dark place away from direct sunlight. Alcohol content preserves indefinitely; discard only if flavor degrades.', 'Manufacturer', NULL),
  (10324, 'Tomatillo', 'fresh', 'Produce', 'Green tomato-like fruit', 'tomatillo fresh green produce', 1, 3, NULL, NULL, 7, 14, NULL, NULL, 180, 365, 'Refrigerate in paper bag or loose in crisper drawer. Remove papery husk before use. Freezing works well for salsas and cooked dishes.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10325, 'Hominy', NULL, 'Grains, Beans & Pasta', 'Canned corn product', 'hominy canned corn nixtamalized', 365, 1095, 3, 7, NULL, NULL, 3, 7, NULL, NULL, 'Unopened cans store at room temperature. After opening, refrigerate in airtight container or freeze for longer storage.', 'FDA', 'https://www.fda.gov/food/foodborneillnesscontaminants/buystoreservesafely/ucm109508.htm'),
  (10326, 'Posole', NULL, 'Grains, Beans & Pasta', 'Dried corn kernels', 'posole dried corn hominy kernels', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in airtight container in cool, dry place. Older dried posole takes longer to cook; use within 1–2 years for best results.', 'Extension', 'https://www.nchfp.uga.edu/'),
  (10327, 'Mexican Oregano', NULL, 'Shelf Stable Foods', 'Dried herb', 'oregano mexican dried herb spice', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in airtight container away from heat, light, and moisture. Flavor fades over time; replace after 1–2 years for best potency.', 'Manufacturer', NULL),
  (10328, 'Epazote', NULL, 'Produce', 'Fresh herb', 'epazote fresh herb mexican cilantro', 0, 1, NULL, NULL, 3, 7, NULL, NULL, 90, 180, 'Refrigerate in damp paper towel inside plastic bag. Use quickly as flavor diminishes rapidly. Freezing works for cooked dishes.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10329, 'Hoja Santa', NULL, 'Produce', 'Fresh herbs', 'hoja santa mexican pepper leaf fresh herb', NULL, NULL, NULL, NULL, 3, 7, 3, 7, 180, 365, 'Store in a plastic bag in the crisper drawer. Wrap stems in damp paper towel to extend freshness. Freezes well for cooking applications.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10330, 'Scotch Bonnet Pepper', NULL, 'Produce', 'Fresh peppers', 'scotch bonnet pepper fresh hot chili', 3, 7, NULL, NULL, 7, 14, 7, 14, 180, 365, 'Store in a paper bag in the crisper to prevent moisture buildup. Freezes whole or sliced for later use in sauces and curries.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10331, 'Habanero Pepper', NULL, 'Produce', 'Fresh peppers', 'habanero pepper fresh hot chili', 3, 7, NULL, NULL, 7, 14, 7, 14, 180, 365, 'Store in a paper bag in the crisper to prevent moisture buildup. Freezes whole or sliced for later use in sauces and curries.', 'Extension', 'https://www.clemson.edu/extension/'),
  (10332, 'Allspice Berries', NULL, 'Shelf Stable Foods', 'Dried spices', 'allspice berries dried spice pimento', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container away from heat, light, and moisture. Flavor diminishes over time; use within 1–2 years for best potency.', 'Manufacturer', NULL),
  (10333, 'Pimento Sauce', NULL, 'Condiments, Sauces & Canned Goods', 'Prepared sauces', 'pimento sauce red pepper condiment', 365, 730, 3, 7, NULL, NULL, 14, 30, NULL, NULL, 'Refrigerate after opening. Transfer to an airtight container if original packaging is opened; discard if mold appears.', 'Manufacturer', NULL),
  (10334, 'Pickapeppa Sauce', NULL, 'Condiments, Sauces & Canned Goods', 'Prepared sauces', 'pickapeppa sauce condiment jamaican', 365, 1095, 7, 30, NULL, NULL, 30, 90, NULL, NULL, 'Refrigerate after opening to extend shelf life. High acidity and salt content preserve the product; discard if off-odor develops.', 'Manufacturer', NULL),
  (10335, 'Cassava Flour', NULL, 'Grains, Beans & Pasta', 'Flours and starches', 'cassava flour starch gluten-free', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container in a cool, dry place away from moisture and pests. Protect from humidity to prevent clumping.', 'Manufacturer', NULL),
  (10336, 'Plantain Flour', NULL, 'Grains, Beans & Pasta', 'Flours and starches', 'plantain flour starch gluten-free', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container in a cool, dry place away from moisture and pests. Protect from humidity to prevent clumping.', 'Manufacturer', NULL),
  (10337, 'Fufu Flour', NULL, 'Grains, Beans & Pasta', 'Flours and starches', 'fufu flour plantain cassava starch', 365, 730, 365, 730, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container in a cool, dry place away from moisture and pests. Protect from humidity to prevent clumping.', 'Manufacturer', NULL),
  (10338, 'Egusi Seeds', NULL, 'Vegetarian Proteins', 'Seeds and nuts', 'egusi seeds melon seeds ground protein', 180, 365, 180, 365, NULL, NULL, NULL, NULL, 365, 730, 'Store in an airtight container in a cool, dry place. Refrigerate or freeze after opening to prevent rancidity, especially if ground.', 'Manufacturer', NULL),
  (10339, 'Palm Oil', NULL, 'Shelf Stable Foods', 'Cooking oils', 'palm oil cooking oil vegetable oil', 365, 730, 180, 365, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in a cool, dark place away from heat and light. Solidifies at room temperature; warm gently before use if needed.', 'Manufacturer', NULL),
  (10340, 'Red Palm Oil', NULL, 'Shelf Stable Foods', 'Cooking oils', 'red palm oil cooking oil vegetable oil', 365, 730, 180, 365, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in a cool, dark place away from heat and light. Color and consistency may vary naturally; this does not indicate spoilage.', 'Manufacturer', NULL),
  (10341, 'Berbere Spice', NULL, 'Condiments, Sauces & Canned Goods', 'Spice blends', 'berbere spice blend ethiopian seasoning', 180, 365, 180, 365, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container in a cool, dark, dry place. Potency fades over time; use within 6 months for best flavor.', 'Manufacturer', NULL),
  (10342, 'Mitmita Spice', NULL, 'Condiments, Sauces & Canned Goods', 'Spice blends', 'mitmita spice blend ethiopian hot pepper', 180, 365, 180, 365, NULL, NULL, NULL, NULL, NULL, NULL, 'Store in an airtight container in a cool, dark, dry place. Potency fades over time; use within 6 months for best flavor.', 'Manufacturer', NULL),
  (10343, 'Niter Kibbeh', NULL, 'Dairy Products & Eggs', 'Clarified butter, spiced', 'niter kibbeh clarified butter spiced ghee ethiopian', 180, 365, 90, 180, 365, 730, 180, 365, 365, 1095, 'Store in an airtight container in a cool, dark place. Refrigerate after opening to extend shelf life. Freezing is recommended for long-term storage.', 'Manufacturer', NULL),
  (10344, 'Injera Bread', NULL, 'Baked Goods', 'Flatbread', 'injera bread ethiopian teff flatbread', 1, 2, NULL, NULL, 3, 5, NULL, NULL, 30, 90, 'Refrigerate to extend freshness. Wrap tightly to prevent drying. Freezes well; thaw at room temperature before serving.', 'Manufacturer', NULL),
  (10345, 'Teff Flour', NULL, 'Grains, Beans & Pasta', 'Whole grain flour', 'teff flour grain ethiopian whole grain', 180, 365, 90, 180, 365, 730, 180, 365, 365, 1095, 'Store in an airtight container in a cool, dry place. Whole grain flours are prone to rancidity; refrigerate or freeze for extended storage.', 'Extension', 'https://www.extension.org'),
  (10346, 'Sorghum Flour', NULL, 'Grains, Beans & Pasta', 'Whole grain flour', 'sorghum flour grain whole grain gluten-free', 180, 365, 90, 180, 365, 730, 180, 365, 365, 1095, 'Store in an airtight container in a cool, dry place. Whole grain flours are prone to rancidity; refrigerate or freeze for extended storage.', 'Extension', 'https://www.extension.org'),
  (10347, 'Fonio Grain', NULL, 'Grains, Beans & Pasta', 'Whole grain', 'fonio grain whole grain african cereal', 180, 365, 90, 180, 365, 730, 180, 365, 365, 1095, 'Store in an airtight container in a cool, dry place. Protect from moisture and pests. Refrigerate or freeze for extended storage.', 'Extension', 'https://www.extension.org'),
  (10348, 'Millet Flour', NULL, 'Grains, Beans & Pasta', 'Whole grain flour', 'millet flour grain whole grain gluten-free', 180, 365, 90, 180, 365, 730, 180, 365, 365, 1095, 'Store in an airtight container in a cool, dry place. Whole grain flours are prone to rancidity; refrigerate or freeze for extended storage.', 'Extension', 'https://www.extension.org'),
  (10349, 'Smetana', 'Eastern European sour cream', 'Dairy Products & Eggs', 'Sour cream & cultured dairy', 'smetana sour cream cultured dairy eastern european', NULL, NULL, NULL, NULL, 7, 14, 7, 10, 60, 90, 'Keep refrigerated at 40°F or below. Freezing may affect texture; thaw in refrigerator before use.', 'Extension', 'https://extension.oregonstate.edu/ask-expert/featured/how-long-can-you-keep-sour-cream'),
  (10350, 'Tvorog', 'Eastern European curd cheese', 'Dairy Products & Eggs', 'Fresh cheese curds', 'tvorog curd cheese fresh cheese eastern european', NULL, NULL, NULL, NULL, 3, 7, 3, 5, 30, 60, 'Highly perishable; store in coldest part of refrigerator. Freezing may separate whey; best used in cooked dishes after thawing.', 'Extension', NULL),
  (10351, 'Farmer Cheese', NULL, 'Dairy Products & Eggs', 'Fresh cheese', 'farmer cheese fresh cheese curd', NULL, NULL, NULL, NULL, 5, 8, 5, 7, 30, 90, 'Keep in coldest part of refrigerator. Texture becomes crumbly when frozen; use thawed cheese in baking or cooked applications.', 'Extension', NULL),
  (10352, 'Brynza', 'Brine-cured cheese', 'Dairy Products & Eggs', 'Aged cheese in brine', 'brynza brine cheese aged cheese', NULL, NULL, NULL, NULL, 14, 30, 14, 21, 60, 180, 'Keep submerged in brine; store in coldest part of refrigerator. Freezing may affect crumbly texture; thaw in refrigerator.', 'Extension', NULL),
  (10353, 'Quark Cheese', NULL, 'Dairy Products & Eggs', 'Fresh cheese', 'quark cheese fresh cheese cultured', NULL, NULL, NULL, NULL, 7, 14, 7, 10, 30, 90, 'Refrigerate immediately. Freezing may separate; thaw in refrigerator and stir before use in desserts or sauces.', 'Manufacturer', NULL),
  (10354, 'Eastern European Kefir', NULL, 'Beverages', 'Cultured milk beverage', 'kefir cultured milk beverage fermented', NULL, NULL, NULL, NULL, 7, 14, 7, 10, 60, 120, 'Keep refrigerated at 40°F or below. Freezing may affect carbonation and texture; thaw in refrigerator.', 'Manufacturer', NULL),
  (10355, 'Borscht Concentrate', NULL, 'Condiments, Sauces & Canned Goods', 'Soup concentrate', 'borscht concentrate soup beet', 365, 730, NULL, NULL, NULL, NULL, 14, 21, 90, 180, 'Store unopened in cool, dry pantry. After opening, refrigerate and use within 2–3 weeks, or freeze in portions.', 'Manufacturer', NULL),
  (10356, 'Bigos Canned', 'Polish hunter''s stew', 'Condiments, Sauces & Canned Goods', 'Canned prepared food', 'bigos canned stew polish hunter', 365, 730, NULL, NULL, NULL, NULL, 3, 4, 60, 120, 'Store unopened in cool, dry pantry. After opening, transfer to airtight container, refrigerate, and use within 3–4 days.', 'Manufacturer', NULL),
  (10357, 'Sauerkraut Polish', NULL, 'Condiments, Sauces & Canned Goods', 'Fermented vegetable', 'sauerkraut polish fermented cabbage', NULL, NULL, NULL, NULL, 30, 90, 30, 60, 180, 365, 'Keep refrigerated and submerged in brine. Flavor and texture improve over time. Freezing may soften texture but preserves flavor.', 'NCHFP', 'https://nchfp.uga.edu'),
  (10358, 'Pierogi Frozen', NULL, 'Food Purchased Frozen', 'Frozen prepared dumpling', 'pierogi frozen dumpling prepared', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 180, 365, 'Keep frozen at 0°F or below. Do not thaw before cooking; boil or pan-fry from frozen. Discard if freezer-burned.', 'Manufacturer', NULL)
